<?php require 'config.php'; if(auth()){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$st=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];redirect('index.php');}$err='البريد الإلكتروني أو كلمة المرور غير صحيحة';} $pdo=db();$settings=$pdo->query('SELECT * FROM settings WHERE id=1')->fetch();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102f3b"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><meta name="apple-mobile-web-app-title" content="أكاديمي"><link rel="apple-touch-icon" href="assets/icons/icon-192.png"><link rel="manifest" href="assets/manifest.json"><link rel="stylesheet" href="assets/style.css"><title>تسجيل الدخول | <?=e($settings['studio_name']??APP_NAME)?></title></head><body class="login"><div class="login-card"><div class="logo-mark">أك</div><h1><?=e($settings['studio_name']??APP_NAME)?></h1><p>نظام إدارة الاستوديو والمحتوى التعليمي</p><?php if($err):?><div class="alert bad"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>البريد الإلكتروني</label><input name="email" type="email" autocomplete="username" required placeholder="admin@akadimi.local"><label>كلمة المرور</label><input name="password" type="password" autocomplete="current-password" required placeholder="••••••••"><button class="primary wide">تسجيل الدخول</button></form><div class="login-help">الحساب الافتراضي<br><b>admin@akadimi.local</b><br><b>Admin@123</b></div></div></body></html>
